-- Check: 4 quizzes, 20 questions and 20 right answers each; each crash course's Class 1 item 4 opens its quiz.
SELECT t.code, COUNT(DISTINCT x.id) AS questions, SUM(o.is_correct) AS right_answers FROM tests t JOIN questions x ON x.test_id = t.id JOIN question_options o ON o.question_id = x.id WHERE t.code IN ('IELTS_ACA_C1_QUIZ', 'IELTS_GT_C1_QUIZ', 'CELPIP_C1_QUIZ', 'PTE_C1_QUIZ') GROUP BY t.code;
SELECT c.folder_name, p.title, p.status, p.test_code FROM lesson_parts p JOIN lessons l ON l.id = p.lesson_id JOIN modules m ON m.id = l.module_id AND m.module_order = 1 JOIN courses c ON c.id = l.course_id WHERE l.lesson_order = 1 AND p.part_order = 4 AND c.folder_name IN ('IELTS_Aca_1Mo', 'IELTS_Gen_1Mo', 'CELPIP_Gen_1Mo', 'PTE_Gen_1Mo');

